import{_ as t,o as a,c as i,a6 as r}from"./chunks/framework.BBdhcoHf.js";const u=JSON.parse('{"title":"ADR-015: P2P Direct Protocol (SBDP)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/015-p2p-direct-protocol.md","filePath":"adr/015-p2p-direct-protocol.md","lastUpdated":0}'),s={name:"adr/015-p2p-direct-protocol.md"};function o(n,e,l,d,c,p){return a(),i("div",null,[...e[0]||(e[0]=[r('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /adr/015-p2p-direct-protocol.md for this page in Markdown format</div><h1 id="adr-015-p2p-direct-protocol-sbdp" tabindex="-1">ADR-015: P2P Direct Protocol (SBDP) <a class="header-anchor" href="#adr-015-p2p-direct-protocol-sbdp" aria-label="Permalink to “ADR-015: P2P Direct Protocol (SBDP)”">​</a></h1><ul><li><strong>Date</strong>: 2026-02-25</li><li><strong>Status</strong>: Accepted</li><li><strong>Affects</strong>: Protocol, SDK, Transport</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>SBRP provides E2EE sessions via a relay server. This works for the primary use case (browser ↔ daemon behind NAT) but introduces relay latency and requires relay infrastructure. Two scenarios call for a direct session layer (SBDP):</p><ol><li><strong>Same-network access</strong> — daemon and client are on the same LAN; relay adds unnecessary round-trip latency.</li><li><strong>Direct daemon-to-daemon</strong> — two server-side peers in the same datacenter or VPC do not benefit from relay.</li></ol><p>The existing architecture was designed to accommodate SBDP without changes to SBP or higher layers. This ADR records the key design decisions before specification work begins, so that speculative P2P design is not driven by premature implementation.</p><h2 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to “Decisions”">​</a></h2><h3 id="_1-defer-until-relay-is-stable" tabindex="-1">1. Defer until relay is stable <a class="header-anchor" href="#_1-defer-until-relay-is-stable" aria-label="Permalink to “1. Defer until relay is stable”">​</a></h3><p>SBDP will not be specified until the hosted relay (SBRP) is production-stable and user demand for direct sessions is validated. The architecture is ready; the implementation is intentionally deferred.</p><p><strong>Rationale:</strong> Premature P2P complexity risks polluting the negotiator contract and transport ABI before they are fully validated in production. The relay path gives real data on session lifecycle edge cases that SBDP will inherit.</p><h3 id="_2-noise-xx-mutual-authentication-—-not-noise-nk" tabindex="-1">2. Noise XX (mutual authentication) — not Noise NK <a class="header-anchor" href="#_2-noise-xx-mutual-authentication-—-not-noise-nk" aria-label="Permalink to “2. Noise XX (mutual authentication) — not Noise NK”">​</a></h3><p>SBRP uses asymmetric authentication: the daemon has an identity keypair; the client has no persistent identity. SBDP requires mutual authentication because both sides are peers with equal standing.</p><p><strong>Chosen protocol:</strong> Noise XX — both sides authenticate their Noise static keypairs (X25519) during the handshake. If Sideband Ed25519 identities are used, they MUST be cryptographically bound to the Noise static key (binding details deferred to the SBDP specification).</p><p><strong>Consequences:</strong></p><ul><li>Both parties must provision Noise static keypairs before a direct session.</li><li>TOFU pinning applies to both directions independently.</li><li>MITM detection works in both directions.</li><li><code>sbdpNegotiator()</code> requires a Noise static keypair from both sides (unlike <code>sbrpClientNegotiator</code> where the client has no persistent identity).</li></ul><h3 id="_3-transport-is-pluggable-no-single-p2p-transport-is-mandated" tabindex="-1">3. Transport is pluggable; no single P2P transport is mandated <a class="header-anchor" href="#_3-transport-is-pluggable-no-single-p2p-transport-is-mandated" aria-label="Permalink to “3. Transport is pluggable; no single P2P transport is mandated”">​</a></h3><p>SBDP is a session layer that wraps SBP frames — it does not mandate a specific P2P transport.</p><table tabindex="0"><thead><tr><th>Context</th><th>Transport</th></tr></thead><tbody><tr><td>Browser ↔ browser</td><td>WebRTC DataChannel</td></tr><tr><td>Browser ↔ daemon</td><td>WebRTC DataChannel (or QUIC if supported)</td></tr><tr><td>Daemon ↔ daemon</td><td>QUIC, raw TCP</td></tr></tbody></table><p>Each transport implements <code>TransportConnection</code> (see ADR-005). SBDP does not inspect which transport is in use.</p><h3 id="_4-nat-traversal-via-relay-assisted-ice-signaling" tabindex="-1">4. NAT traversal via relay-assisted ICE signaling <a class="header-anchor" href="#_4-nat-traversal-via-relay-assisted-ice-signaling" aria-label="Permalink to “4. NAT traversal via relay-assisted ICE signaling”">​</a></h3><p>Browser-based P2P requires ICE/STUN/TURN for NAT traversal. The preferred strategy is to use the existing SBRP relay connection only for ICE candidate exchange (signaling), then transition to a direct WebRTC DataChannel once the hole punch succeeds.</p><ul><li><strong>Happy path</strong>: relay forwards ICE candidates → direct DataChannel connected → Noise XX handshake completes over the direct transport → SBRP connection closed. SBRP MUST NOT be closed before the direct SBDP session is cryptographically active.</li><li><strong>Fallback</strong>: if direct DataChannel cannot be established (symmetric NAT), remain on relay (SBRP).</li></ul><p>The transition is modeled as a negotiator-managed channel switch (new <code>SessionChannel</code>), not as a new public peer state. No user API change is needed; the active channel is an internal concern of the negotiator/runtime boundary.</p><h3 id="_5-peer-discovery-is-out-of-scope-for-the-sdk" tabindex="-1">5. Peer discovery is out of scope for the SDK <a class="header-anchor" href="#_5-peer-discovery-is-out-of-scope-for-the-sdk" aria-label="Permalink to “5. Peer discovery is out of scope for the SDK”">​</a></h3><p>SBDP assumes the remote peer&#39;s address (or ICE candidates) are known. How peers discover each other is an application concern:</p><ul><li><strong>Local network</strong>: mDNS / Bonjour, explicit IP configuration</li><li><strong>Same datacenter</strong>: service registry, DNS SRV</li><li><strong>Internet</strong>: rendezvous server, relay-assisted</li></ul><p>Discovery APIs will not be added to <code>@sideband/peer</code>. Applications resolve addresses and pass them to the transport.</p><h2 id="invariants" tabindex="-1">Invariants <a class="header-anchor" href="#invariants" aria-label="Permalink to “Invariants”">​</a></h2><ul><li>SBDP MUST treat SBP frames as opaque bytes — no inspection of subjects or frame content.</li><li>Both peers in an SBDP session MUST provision Noise static keypairs (X25519) before the handshake begins.</li><li>TOFU pinning MUST be applied in both directions.</li><li>The transport ABI (ADR-005) is unchanged; SBDP introduces no new transport primitives.</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives Considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to “Alternatives Considered”">​</a></h2><p><strong>Noise NK / NX</strong>: One-sided authentication like SBRP. Rejected because SBDP peers have symmetric roles — forcing one side to be anonymous weakens the security model without simplifying the API.</p><p><strong>DTLS</strong>: Widely deployed but not available as a WebCrypto primitive in browsers. Would require a WASM implementation or platform-specific code path, complicating the transport abstraction.</p><p><strong>QUIC for browsers</strong>: Not yet widely available via WebTransport in all targets. Deferred to a later transport implementation; SBDP does not depend on it.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><code>@sideband/sbdp</code> will be a new package (parallel to <code>@sideband/secure-relay</code>) when implemented.</li><li><code>sbdpNegotiator()</code> will live in <code>@sideband/peer</code> (same pattern as SBRP negotiators, see ADR-013).</li><li><code>@sideband/transport-webrtc</code> will be a separate package implementing the transport ABI for WebRTC.</li><li>No changes to SBP, runtime, router, or RPC layers.</li><li>Mutual TOFU means the daemon/server side will need an <code>identityKeyStore</code> to persist and validate inbound client keys — a new requirement compared to SBRP where clients are anonymous.</li><li>Relay-assisted ICE signaling requires a coordination message type in the relay protocol — this will be specified as an SBRP extension when SBDP design begins.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to “References”">​</a></h2><ul><li>ADR-005: Transport ABI</li><li>ADR-009: Runtime Session Lifecycle (negotiator contract)</li><li>ADR-013: Peer SDK Design (negotiator factory pattern)</li><li>ADR-014: Session Signal Handling (pause/resume semantics for SBRP)</li><li><code>docs/protocols/sbdp/index.md</code>: SBDP protocol stub</li><li><code>docs/protocols/sbdp/design.md</code>: SBDP design document</li><li><code>docs/protocols/sbrp/</code>: Reference implementation for session layer pattern</li></ul>',38)])])}const m=t(s,[["render",o]]);export{u as __pageData,m as default};
